    "functions": [
        {
            "schema": "rrhh",
            "functions": [
                {
                    "arguments": "p_email character varying, p_numero_documento character varying, p_nombres character varying, p_apellidos character varying, p_id_solicitud uuid, p_expires_in_minutes integer DEFAULT 1440",
                    "definition": "CREATE OR REPLACE FUNCTION rrhh.fn_generate_registration_code(p_email character varying, p_numero_documento character varying, p_nombres character varying, p_apellidos character varying, p_id_solicitud uuid, p_expires_in_minutes integer DEFAULT 1440)\n RETURNS rrhh.codigos_registro_voluntario\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nDECLARE\r\n  v_row rrhh.codigos_registro_voluntario;\r\n  v_code text;\r\nBEGIN\r\n  IF NOT public.fn_has_permission('volunteers.invite') AND NOT public.fn_is_tenant_admin() THEN\r\n    RAISE EXCEPTION 'No autorizado';\r\n  END IF;\r\n\r\n  v_code := upper(substr(encode(gen_random_bytes(8), 'hex'), 1, 12));\r\n\r\n  INSERT INTO rrhh.codigos_registro_voluntario(\r\n    tenant_id, codigo, email_objetivo, numero_documento_objetivo, nombres_objetivo,\r\n    apellidos_objetivo, id_solicitud, expires_at, created_by, updated_by\r\n  )\r\n  VALUES (\r\n    public.fn_current_tenant_id(), v_code, p_email, p_numero_documento, p_nombres,\r\n    p_apellidos, p_id_solicitud, now() + make_interval(mins => p_expires_in_minutes),\r\n    auth.uid(), auth.uid()\r\n  )\r\n  RETURNING * INTO v_row;\r\n\r\n  RETURN v_row;\r\nEND;\r\n$function$\n",
                    "return_type": "rrhh.codigos_registro_voluntario",
                    "function_name": "fn_generate_registration_code"
                }
            ]
        },
