                    "definition": "CREATE OR REPLACE FUNCTION gym.current_gym_id()\n RETURNS uuid\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'gym', 'public', 'auth'\nAS $function$\r\n  SELECT id_gimnasio FROM gym.usuarios WHERE id_usuario = auth.uid()\r\n$function$\n",
                    "return_type": "uuid",
                    "function_name": "current_gym_id"
