                {
                    "arguments": "p_nombre text, p_ruc text DEFAULT NULL::text, p_ciudad text DEFAULT 'Lima'::text, p_pais text DEFAULT 'Perú'::text, p_direccion text DEFAULT NULL::text, p_telefono text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_plan text DEFAULT 'mediano'::text, p_cargo text DEFAULT 'Gerente General'::text",
                    "definition": "CREATE OR REPLACE FUNCTION gym.bootstrap_gym_tenant(p_nombre text, p_ruc text DEFAULT NULL::text, p_ciudad text DEFAULT 'Lima'::text, p_pais text DEFAULT 'Perú'::text, p_direccion text DEFAULT NULL::text, p_telefono text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_plan text DEFAULT 'mediano'::text, p_cargo text DEFAULT 'Gerente General'::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'gym', 'public', 'auth'\nAS $function$\r\nDECLARE\r\n  v_user_id    UUID := auth.uid();\r\n  v_gym_id     UUID;\r\n  v_code       TEXT;\r\nBEGIN\r\n  -- 1. Verificar autenticación\r\n  IF v_user_id IS NULL THEN\r\n    RAISE EXCEPTION 'No autenticado';\r\n  END IF;\r\n\r\n  -- 2. Verificar que el usuario no tenga ya un gym asignado\r\n  IF EXISTS (\r\n    SELECT 1 FROM gym.usuarios\r\n     WHERE id_usuario = v_user_id AND id_gimnasio IS NOT NULL\r\n  ) THEN\r\n    RAISE EXCEPTION 'El usuario ya tiene un gimnasio registrado';\r\n  END IF;\r\n\r\n  -- 3. Crear el gimnasio\r\n  INSERT INTO gym.gimnasios (\r\n    nombre, ruc, ciudad, pais, direccion, telefono, email,\r\n    plan_suscripcion, estado\r\n  )\r\n  VALUES (\r\n    p_nombre, p_ruc, p_ciudad, p_pais, p_direccion,\r\n    p_telefono, p_email, p_plan, 'activo'\r\n  )\r\n  RETURNING id_gimnasio INTO v_gym_id;\r\n\r\n  -- 4. Generar y registrar código de acceso\r\n  v_code := public.generate_gym_code(p_nombre);\r\n  INSERT INTO gym.codigos_acceso (id_gimnasio, codigo, tipo, descripcion, creado_por)\r\n  VALUES (v_gym_id, v_code, 'general', 'Código principal', v_user_id);\r\n\r\n  -- 5. Actualizar perfil del usuario → asignarlo como gerente del gym\r\n  UPDATE gym.usuarios\r\n     SET id_gimnasio = v_gym_id,\r\n         rol         = 'gerente',\r\n         cargo       = COALESCE(cargo, p_cargo),\r\n         estado      = 'activo'\r\n   WHERE id_usuario = v_user_id;\r\n\r\n  -- Si el usuario aún no tiene fila en gym.usuarios, crearla\r\n  IF NOT FOUND THEN\r\n    INSERT INTO gym.usuarios (id_usuario, email, nombre, cargo, id_gimnasio, rol, estado)\r\n    SELECT\r\n      v_user_id,\r\n      au.email,\r\n      COALESCE(NULLIF(au.raw_user_meta_data->>'nombre', ''), split_part(au.email, '@', 1)),\r\n      p_cargo,\r\n      v_gym_id,\r\n      'gerente',\r\n      'activo'\r\n    FROM auth.users au WHERE au.id = v_user_id\r\n    ON CONFLICT (id_usuario) DO UPDATE\r\n      SET id_gimnasio = v_gym_id, rol = 'gerente', cargo = p_cargo;\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object(\r\n    'ok',          true,\r\n    'id_gimnasio', v_gym_id,\r\n    'codigo',      v_code,\r\n    'plan',        p_plan\r\n  );\r\n\r\nEXCEPTION WHEN OTHERS THEN\r\n  RAISE EXCEPTION 'bootstrap_gym_tenant: % (%)', SQLERRM, SQLSTATE;\r\nEND;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "bootstrap_gym_tenant"
                },
                {
                    "arguments": "",
                    "definition": "CREATE OR REPLACE FUNCTION gym.fn_sync_usuario_rol_to_rbac()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'gym', 'public', 'auth'\nAS $function$\r\nDECLARE\r\n  v_tenant_id  UUID;\r\n  v_role_name  TEXT;\r\n  v_role_id    UUID;\r\n  -- Conjunto de nombres de rol de sistema \"mapeables\" desde el gimnasio.\r\n  -- Se usa para acotar el borrado del rol anterior SIN tocar roles de otros\r\n  -- módulos (p.ej. ONG) ni asignaciones manuales.\r\n  v_gym_role_names TEXT[] := ARRAY[\r\n    'Administrador General','Supervisor','Cajero',\r\n    'Recepcionista','Entrenador','Nutricionista','Miembro'\r\n  ];\r\nBEGIN\r\n  -- Lógica protegida: cualquier error se captura abajo y NO propaga al INSERT/UPDATE.\r\n  BEGIN\r\n\r\n    -- 1.a Derivar el tenant_id del gimnasio del usuario (gym.usuarios no lo almacena).\r\n    SELECT g.tenant_id\r\n      INTO v_tenant_id\r\n      FROM gym.gimnasios g\r\n     WHERE g.id_gimnasio = NEW.id_gimnasio;\r\n\r\n    -- 1.b Mapear el enum de texto rol → nombre canónico en public.roles.\r\n    v_role_name := CASE lower(COALESCE(NEW.rol, ''))\r\n      WHEN 'admin'         THEN 'Administrador General'\r\n      WHEN 'gerente'       THEN 'Administrador General'  -- dueño/gerente = admin del tenant gym\r\n      WHEN 'recepcionista' THEN 'Recepcionista'\r\n      WHEN 'entrenador'    THEN 'Entrenador'\r\n      WHEN 'nutricionista' THEN 'Nutricionista'\r\n      WHEN 'miembro'       THEN 'Miembro'\r\n      WHEN 'cliente'       THEN 'Miembro'                -- cliente se trata como miembro\r\n      ELSE NULL                                          -- sin equivalente RBAC (p.ej. rol nuevo)\r\n    END;\r\n\r\n    -- 1.c Guardas de resiliencia: sin tenant o sin mapeo → advertir y salir sin bloquear.\r\n    IF v_tenant_id IS NULL THEN\r\n      PERFORM gym._log_sync_warning(\r\n        NULL, NEW.id_usuario, NEW.rol,\r\n        'tenant_id NULL: gimnasio ' || COALESCE(NEW.id_gimnasio::text,'(null)') ||\r\n        ' sin tenant vinculado; no se sincroniza RBAC.'\r\n      );\r\n      RETURN NEW;\r\n    END IF;\r\n\r\n    IF v_role_name IS NULL THEN\r\n      PERFORM gym._log_sync_warning(\r\n        v_tenant_id, NEW.id_usuario, NEW.rol,\r\n        'rol sin equivalente en catálogo maestro; no se sincroniza RBAC.'\r\n      );\r\n      RETURN NEW;\r\n    END IF;\r\n\r\n    -- 1.d Resolver el role_id en el catálogo maestro para ese tenant.\r\n    SELECT r.id\r\n      INTO v_role_id\r\n      FROM public.roles r\r\n     WHERE r.tenant_id = v_tenant_id\r\n       AND r.name      = v_role_name\r\n     LIMIT 1;\r\n\r\n    IF v_role_id IS NULL THEN\r\n      PERFORM gym._log_sync_warning(\r\n        v_tenant_id, NEW.id_usuario, NEW.rol,\r\n        'rol \"' || v_role_name || '\" no existe en public.roles para el tenant; ' ||\r\n        'ejecutar seed de roles (migración 016) antes de sincronizar.'\r\n      );\r\n      RETURN NEW;\r\n    END IF;\r\n\r\n    -- 1.e Si el rol cambió: retirar asignaciones previas de roles-gimnasio distintas\r\n    --     a la nueva (acotado a v_gym_role_names para no borrar roles de otros módulos).\r\n    DELETE FROM public.user_roles ur\r\n     WHERE ur.tenant_id = v_tenant_id\r\n       AND ur.user_id   = NEW.id_usuario\r\n       AND ur.role_id  <> v_role_id\r\n       AND ur.role_id IN (\r\n             SELECT r.id FROM public.roles r\r\n              WHERE r.tenant_id = v_tenant_id\r\n                AND r.name = ANY(v_gym_role_names)\r\n           );\r\n\r\n    -- 1.f Garantizar la asignación equivalente (idempotente).\r\n    INSERT INTO public.user_roles (tenant_id, user_id, role_id, assigned_by, assigned_at)\r\n    VALUES (v_tenant_id, NEW.id_usuario, v_role_id, NULL, now())\r\n    ON CONFLICT (tenant_id, user_id, role_id) DO NOTHING;\r\n\r\n    RETURN NEW;\r\n\r\n  EXCEPTION\r\n    WHEN OTHERS THEN\r\n      -- Resiliencia total: registrar y continuar. El write del gimnasio no se revierte.\r\n      PERFORM gym._log_sync_warning(\r\n        v_tenant_id, NEW.id_usuario, NEW.rol,\r\n        'Excepción en sync RBAC: ' || SQLERRM\r\n      );\r\n      RETURN NEW;\r\n  END;\r\nEND;\r\n$function$\n",
                    "return_type": "trigger",
                    "function_name": "fn_sync_usuario_rol_to_rbac"
                },
                {
                    "arguments": "p_tenant_id uuid, p_user_id uuid, p_rol text, p_detail text",
                    "definition": "CREATE OR REPLACE FUNCTION gym._log_sync_warning(p_tenant_id uuid, p_user_id uuid, p_rol text, p_detail text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'gym'\nAS $function$\r\nBEGIN\r\n  RAISE WARNING '[sync_gym_rol_to_rbac] user=% rol=% tenant=% :: %',\r\n    p_user_id, p_rol, p_tenant_id, p_detail;\r\n\r\n  -- Persistir el aviso; si audit_logs no acepta la fila, no se propaga el error.\r\n  BEGIN\r\n    INSERT INTO public.audit_logs (tenant_id, actor_id, event_type, resource_name, payload_after)\r\n    VALUES (\r\n      p_tenant_id,\r\n      p_user_id,\r\n      'SYNC_WARNING',\r\n      'gym.usuarios.rol->public.user_roles',\r\n      jsonb_build_object('rol', p_rol, 'detail', p_detail, 'at', now())\r\n    );\r\n  EXCEPTION WHEN OTHERS THEN\r\n    NULL;  -- el RAISE WARNING ya dejó traza; nunca bloquear.\r\n  END;\r\nEND;\r\n$function$\n",
                    "return_type": "void",
                    "function_name": "_log_sync_warning"
                },
                {
                    "arguments": "p_codigo text, p_nombre text DEFAULT NULL::text, p_cargo text DEFAULT NULL::text",
                    "definition": "CREATE OR REPLACE FUNCTION gym.join_gym_with_code(p_codigo text, p_nombre text DEFAULT NULL::text, p_cargo text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'gym', 'public', 'auth'\nAS $function$\r\nDECLARE\r\n  v_user_id   UUID := auth.uid();\r\n  v_gym_id    UUID;\r\n  v_code_id   UUID;\r\n  v_max_usos  INT;\r\n  v_usos_act  INT;\r\nBEGIN\r\n  IF v_user_id IS NULL THEN\r\n    RAISE EXCEPTION 'No autenticado';\r\n  END IF;\r\n\r\n  -- Buscar el código activo\r\n  SELECT id_codigo, id_gimnasio, usos_max, usos_actuales\r\n    INTO v_code_id, v_gym_id, v_max_usos, v_usos_act\r\n    FROM gym.codigos_acceso\r\n   WHERE codigo = upper(trim(p_codigo))\r\n     AND activo = TRUE\r\n     AND (fecha_expiracion IS NULL OR fecha_expiracion > NOW())\r\n   LIMIT 1;\r\n\r\n  IF v_code_id IS NULL THEN\r\n    RAISE EXCEPTION 'Código inválido, inactivo o expirado';\r\n  END IF;\r\n\r\n  -- Verificar límite de usos\r\n  IF v_max_usos IS NOT NULL AND v_usos_act >= v_max_usos THEN\r\n    RAISE EXCEPTION 'El código ya alcanzó su límite de usos';\r\n  END IF;\r\n\r\n  -- Asignar gym al perfil del usuario (si aún no tiene uno)\r\n  UPDATE gym.usuarios\r\n     SET id_gimnasio = v_gym_id,\r\n         nombre      = COALESCE(NULLIF(p_nombre, ''), nombre),\r\n         cargo       = COALESCE(NULLIF(p_cargo, ''), cargo),\r\n         estado      = 'activo'\r\n   WHERE id_usuario = v_user_id\r\n     AND id_gimnasio IS NULL;\r\n\r\n  -- Si no tenía perfil, crearlo\r\n  IF NOT FOUND THEN\r\n    INSERT INTO gym.usuarios (id_usuario, email, nombre, cargo, id_gimnasio, rol, estado)\r\n    SELECT\r\n      v_user_id,\r\n      au.email,\r\n      COALESCE(NULLIF(p_nombre, ''), NULLIF(au.raw_user_meta_data->>'nombre', ''), split_part(au.email, '@', 1)),\r\n      p_cargo,\r\n      v_gym_id,\r\n      'miembro',\r\n      'activo'\r\n    FROM auth.users au WHERE au.id = v_user_id\r\n    ON CONFLICT (id_usuario) DO UPDATE\r\n      SET id_gimnasio = v_gym_id, estado = 'activo';\r\n  END IF;\r\n\r\n  -- Incrementar contador de usos del código\r\n  UPDATE gym.codigos_acceso\r\n     SET usos_actuales = usos_actuales + 1\r\n   WHERE id_codigo = v_code_id;\r\n\r\n  RETURN jsonb_build_object(\r\n    'ok',          true,\r\n    'id_gimnasio', v_gym_id,\r\n    'codigo',      p_codigo\r\n  );\r\n\r\nEXCEPTION WHEN OTHERS THEN\r\n  RAISE EXCEPTION 'join_gym_with_code: %', SQLERRM;\r\nEND;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "join_gym_with_code"
                }
            ]
