                    "definition": "CREATE OR REPLACE FUNCTION public.fn_remote_revoke_app_session(p_session_id uuid, p_reason text)\n RETURNS sessions\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nDECLARE\r\n  v_session public.sessions;\r\nBEGIN\r\n  IF NOT public.fn_has_permission('settings.sessions.terminate') AND NOT public.fn_is_tenant_admin() THEN\r\n    RAISE EXCEPTION 'No autorizado';\r\n  END IF;\r\n\r\n  UPDATE public.sessions\r\n  SET revoked_at = now(),\r\n      revoke_reason = p_reason\r\n  WHERE id = p_session_id\r\n    AND tenant_id = public.fn_current_tenant_id()\r\n  RETURNING * INTO v_session;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Sesion no encontrada';\r\n  END IF;\r\n\r\n  RETURN v_session;\r\nEND;\r\n$function$\n",
