                    "definition": "CREATE OR REPLACE FUNCTION public.fn_get_my_profile()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_uid UUID := auth.uid();\r\n  v_row public.profiles%ROWTYPE;\r\nBEGIN\r\n  IF v_uid IS NULL THEN\r\n    RETURN jsonb_build_object('found', false, 'reason', 'not_authenticated');\r\n  END IF;\r\n\r\n  SELECT * INTO v_row FROM public.profiles WHERE id = v_uid;\r\n\r\n  IF v_row.id IS NULL THEN\r\n    RETURN jsonb_build_object('found', false, 'reason', 'no_profile');\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object(\r\n    'found',            true,\r\n    'id',               v_row.id,\r\n    'full_name',        v_row.full_name,\r\n    'avatar_url',       v_row.avatar_url,\r\n    'genero',           v_row.genero,\r\n    'numero_documento', v_row.numero_documento,\r\n    'tenant_id',        v_row.tenant_id\r\n  );\r\nEND;\r\n$function$\n",
