                {
                    "arguments": "",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_trigger_audit_universal()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_actor_id       uuid := auth.uid();\r\n  v_payload_before jsonb;\r\n  v_payload_after  jsonb;\r\n  v_tenant_id      uuid;\r\n  v_resource_name  text := format('%I.%I', TG_TABLE_SCHEMA, TG_TABLE_NAME);\r\nBEGIN\r\n  -- Serialización universal OLD/NEW a JSONB: to_jsonb() funciona igual sin\r\n  -- importar de qué esquema/tabla venga la fila (ong, rrhh, gym, ...) — por\r\n  -- eso una SOLA función puede ser reusada como trigger por ambos sistemas.\r\n  v_payload_before := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;\r\n  v_payload_after  := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;\r\n\r\n  -- (a) Intento directo: leer 'tenant_id' del payload JSONB ya serializado\r\n  -- (NEW primero; en DELETE, payload_after es NULL y cae a payload_before/OLD).\r\n  -- ->> retorna NULL en vez de lanzar error si la tabla no tiene esa columna,\r\n  -- lo que permite auto-detectar tablas de 'gym' sin columna tenant_id propia.\r\n  v_tenant_id := COALESCE(\r\n    v_payload_after  ->> 'tenant_id',\r\n    v_payload_before ->> 'tenant_id'\r\n  )::uuid;\r\n\r\n  -- (b) Fallback multi-tenant: la tabla de origen no tiene tenant_id propio\r\n  -- -> resolver vía profiles usando el actor autenticado, igual criterio que\r\n  -- fn_current_tenant_id(). Así ningún log queda huérfano de inquilino.\r\n  IF v_tenant_id IS NULL THEN\r\n    SELECT p.tenant_id\r\n      INTO v_tenant_id\r\n    FROM public.profiles p\r\n    WHERE p.id = v_actor_id\r\n    LIMIT 1;\r\n  END IF;\r\n\r\n  -- Salvaguarda heredada: audit_logs.tenant_id es NOT NULL. Si ni (a) ni (b)\r\n  -- resolvieron un tenant (p. ej. pre-onboarding sin profile asignado aún),\r\n  -- se omite el registro en vez de romper la transacción del llamador.\r\n  IF v_tenant_id IS NULL THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs(\r\n    tenant_id,\r\n    actor_id,\r\n    event_type,\r\n    resource_name,\r\n    payload_before,\r\n    payload_after,\r\n    ip,\r\n    user_agent,\r\n    retention_until\r\n  )\r\n  VALUES (\r\n    v_tenant_id,\r\n    v_actor_id,\r\n    TG_OP,            -- 'INSERT' | 'UPDATE' | 'DELETE'\r\n    v_resource_name,  -- 'esquema.tabla', ej. 'gym.members' u 'ong.activities'\r\n    v_payload_before,\r\n    v_payload_after,\r\n    NULL,\r\n    NULL,\r\n    now() + make_interval(days =>\r\n      COALESCE(\r\n        (\r\n          SELECT pp.retention_days\r\n          FROM public.tenants t\r\n          JOIN public.plan_policies pp ON pp.plan_id = t.plan_id\r\n          WHERE t.id = v_tenant_id\r\n          LIMIT 1\r\n        ),\r\n        180\r\n      )\r\n    )\r\n  );\r\n\r\n  RETURN NULL;\r\nEND;\r\n$function$\n",
                    "return_type": "trigger",
                    "function_name": "fn_trigger_audit_universal"
                },
                {
                    "arguments": "p_plan text",
                    "definition": "CREATE OR REPLACE FUNCTION public._gym_plan_to_bd(p_plan text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\nAS $function$\r\n  SELECT CASE p_plan\r\n    WHEN 'pequeno'    THEN 'basic'\r\n    WHEN 'mediano'    THEN 'pro'\r\n    WHEN 'grande'     THEN 'pro'\r\n    WHEN 'enterprise' THEN 'enterprise'\r\n    ELSE 'basic'\r\n  END;\r\n$function$\n",
                    "return_type": "text",
                    "function_name": "_gym_plan_to_bd"
                },
                {
                    "arguments": "p_plan text",
                    "definition": "CREATE OR REPLACE FUNCTION public._gym_plan_to_licenses(p_plan text)\n RETURNS integer\n LANGUAGE sql\n IMMUTABLE\nAS $function$\r\n  SELECT CASE p_plan\r\n    WHEN 'pequeno'    THEN 100\r\n    WHEN 'mediano'    THEN 500\r\n    WHEN 'grande'     THEN 2000\r\n    WHEN 'enterprise' THEN 99999\r\n    ELSE 100\r\n  END;\r\n$function$\n",
                    "return_type": "integer",
                    "function_name": "_gym_plan_to_licenses"
                },
                {
                    "arguments": "p_tenant_name text, p_tax_id text, p_industry_type_id text, p_plan_id text DEFAULT 'basic'::text, p_billing_day integer DEFAULT 1",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_bootstrap_tenant(p_tenant_name text, p_tax_id text, p_industry_type_id text, p_plan_id text DEFAULT 'basic'::text, p_billing_day integer DEFAULT 1)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_user_id uuid := auth.uid();\r\n  v_existing_tenant_id uuid;\r\n  v_tenant_id uuid;\r\n  v_sede_id uuid;\r\n  v_role_owner_id uuid;\r\nBEGIN\r\n  IF v_user_id IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF COALESCE(trim(p_tenant_name), '') = '' THEN\r\n    RAISE EXCEPTION 'tenant_name is required';\r\n  END IF;\r\n\r\n  IF p_tax_id IS NULL OR p_tax_id !~ '^[0-9]{11}$' THEN\r\n    RAISE EXCEPTION 'tax_id must be an 11-digit RUC';\r\n  END IF;\r\n\r\n  IF p_billing_day IS NULL OR p_billing_day < 1 OR p_billing_day > 28 THEN\r\n    RAISE EXCEPTION 'billing_day must be between 1 and 28';\r\n  END IF;\r\n\r\n  -- Idempotencia: si el usuario ya tiene tenant, se retorna el existente.\r\n  SELECT p.tenant_id\r\n    INTO v_existing_tenant_id\r\n  FROM public.profiles p\r\n  WHERE p.id = v_user_id\r\n  LIMIT 1;\r\n\r\n  IF v_existing_tenant_id IS NOT NULL THEN\r\n    RETURN v_existing_tenant_id;\r\n  END IF;\r\n\r\n  -- 1) Crear tenant primero.\r\n  INSERT INTO public.tenants(name, tax_id, industry_type_id, plan_id, status_financial_id, billing_day, max_licenses)\r\n  VALUES (p_tenant_name, p_tax_id, p_industry_type_id, p_plan_id, 'FIN-ACTIVE', p_billing_day, 1)\r\n  RETURNING id INTO v_tenant_id;\r\n\r\n  -- 2) Upsert profile con tenant_id ya resuelto (evita auditoría con tenant null).\r\n  INSERT INTO public.profiles(id, tenant_id, full_name)\r\n  VALUES (v_user_id, v_tenant_id, NULL)\r\n  ON CONFLICT (id) DO UPDATE\r\n    SET tenant_id = excluded.tenant_id;\r\n\r\n  -- 3) Crear sede principal.\r\n  INSERT INTO public.sedes(tenant_id, name, is_active)\r\n  VALUES (v_tenant_id, 'Principal', true)\r\n  RETURNING id INTO v_sede_id;\r\n\r\n  -- 4) Crear rol Owner.\r\n  INSERT INTO public.roles(tenant_id, name, hierarchy_level, is_system_role)\r\n  VALUES (v_tenant_id, 'Owner', 0, true)\r\n  RETURNING id INTO v_role_owner_id;\r\n\r\n  -- 5) Asignar permisos al Owner (no-op si cat_permissions aún no está poblada).\r\n  INSERT INTO public.role_permissions(role_id, permission)\r\n  SELECT v_role_owner_id, p.id\r\n  FROM public.cat_permissions p\r\n  ON CONFLICT DO NOTHING;\r\n\r\n  -- 6) Asignar Owner al creador.\r\n  INSERT INTO public.user_roles_sedes(tenant_id, user_id, role_id, sede_id)\r\n  VALUES (v_tenant_id, v_user_id, v_role_owner_id, v_sede_id)\r\n  ON CONFLICT DO NOTHING;\r\n\r\n  -- 7) Crear/actualizar contrato — [AUDIT-GAP] requiere public.subscription_contracts (fuera de alcance).\r\n  INSERT INTO public.subscription_contracts(\r\n    tenant_id, current_plan_id, status_id, billing_day, grace_days\r\n  )\r\n  VALUES (v_tenant_id, p_plan_id, 'ACTIVE', p_billing_day, 7)\r\n  ON CONFLICT (tenant_id) DO UPDATE\r\n    SET current_plan_id = excluded.current_plan_id,\r\n        status_id = excluded.status_id,\r\n        billing_day = excluded.billing_day,\r\n        updated_at = now();\r\n\r\n  -- 8) Crear/actualizar entitlements — [AUDIT-GAP] requiere public.entitlements y\r\n  --    public.plan_policies (fuera de alcance).\r\n  INSERT INTO public.entitlements(tenant_id, plan_id, max_sedes, max_licenses, can_use_terminals)\r\n  SELECT v_tenant_id, pp.plan_id, pp.max_sedes, pp.max_licenses, pp.can_use_terminals\r\n  FROM public.plan_policies pp\r\n  WHERE pp.plan_id = p_plan_id\r\n  ON CONFLICT (tenant_id) DO UPDATE\r\n    SET plan_id = excluded.plan_id,\r\n        max_sedes = excluded.max_sedes,\r\n        max_licenses = excluded.max_licenses,\r\n        can_use_terminals = excluded.can_use_terminals,\r\n        updated_at = now();\r\n\r\n  RETURN v_tenant_id;\r\nEND;\r\n$function$\n",
                    "return_type": "uuid",
                    "function_name": "fn_bootstrap_tenant"
                },
                {
                    "arguments": "p_code text, p_type_id text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_validate_code(p_code text, p_type_id text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_row public.codes;\r\nBEGIN\r\n  SELECT * INTO v_row\r\n  FROM public.codes\r\n  WHERE code    = upper(trim(p_code))\r\n    AND status  = 'active'\r\n    AND (expires_at IS NULL OR expires_at > now())\r\n    AND (p_type_id   IS NULL OR type_id   = p_type_id)\r\n    AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)\r\n  LIMIT 1;\r\n\r\n  IF v_row.id IS NULL THEN\r\n    RETURN jsonb_build_object(\r\n      'valid',  false,\r\n      'reason', 'Código inválido, expirado o inactivo'\r\n    );\r\n  END IF;\r\n\r\n  IF v_row.max_uses IS NOT NULL AND v_row.current_uses >= v_row.max_uses THEN\r\n    RETURN jsonb_build_object(\r\n      'valid',  false,\r\n      'reason', 'Límite de usos alcanzado'\r\n    );\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object(\r\n    'valid',          true,\r\n    'code_id',        v_row.id,\r\n    'tenant_id',      v_row.tenant_id,\r\n    'type_id',        v_row.type_id,\r\n    'description',    v_row.description,\r\n    'remaining_uses', CASE\r\n                        WHEN v_row.max_uses IS NULL THEN NULL\r\n                        ELSE v_row.max_uses - v_row.current_uses\r\n                      END,\r\n    'expires_at',     v_row.expires_at,\r\n    'metadata',       v_row.metadata\r\n  );\r\nEND;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_validate_code"
                },
                {
                    "arguments": "p_code text, p_module_name text, p_type_id text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid, p_observations text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_metadata jsonb DEFAULT '{}'::jsonb",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_use_code(p_code text, p_module_name text, p_type_id text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid, p_observations text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_row      public.codes;\r\n  v_usage_id UUID;\r\n  v_new_status TEXT;\r\nBEGIN\r\n  -- Lock the row to prevent double-spending under concurrent requests\r\n  SELECT * INTO v_row\r\n  FROM public.codes\r\n  WHERE code    = upper(trim(p_code))\r\n    AND status  = 'active'\r\n    AND (expires_at IS NULL OR expires_at > now())\r\n    AND (p_type_id   IS NULL OR type_id   = p_type_id)\r\n    AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)\r\n  LIMIT 1\r\n  FOR UPDATE;\r\n\r\n  IF v_row.id IS NULL THEN\r\n    RETURN jsonb_build_object('ok', false, 'error', 'Código inválido, expirado o inactivo');\r\n  END IF;\r\n\r\n  IF v_row.max_uses IS NOT NULL AND v_row.current_uses >= v_row.max_uses THEN\r\n    RETURN jsonb_build_object('ok', false, 'error', 'Límite de usos alcanzado');\r\n  END IF;\r\n\r\n  -- Determinar nuevo estado\r\n  v_new_status := CASE\r\n    WHEN v_row.max_uses IS NOT NULL AND (v_row.current_uses + 1) >= v_row.max_uses\r\n      THEN 'used'\r\n    ELSE 'active'\r\n  END;\r\n\r\n  -- Incrementar uso y actualizar estado si corresponde\r\n  UPDATE public.codes\r\n     SET current_uses = current_uses + 1,\r\n         status       = v_new_status\r\n   WHERE id = v_row.id;\r\n\r\n  -- Registrar auditoría\r\n  INSERT INTO public.code_usages (\r\n    code_id, tenant_id, used_by, module_name, observations, ip_address, metadata\r\n  )\r\n  VALUES (\r\n    v_row.id, v_row.tenant_id, auth.uid(),\r\n    p_module_name, p_observations, p_ip_address, p_metadata\r\n  )\r\n  RETURNING id INTO v_usage_id;\r\n\r\n  RETURN jsonb_build_object(\r\n    'ok',        true,\r\n    'code_id',   v_row.id,\r\n    'usage_id',  v_usage_id,\r\n    'tenant_id', v_row.tenant_id,\r\n    'type_id',   v_row.type_id,\r\n    'metadata',  v_row.metadata,\r\n    'new_status', v_new_status\r\n  );\r\nEND;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_use_code"
                },
                {
                    "arguments": "p_tenant_id uuid, p_type_id text, p_code text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_max_uses integer DEFAULT NULL::integer, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_create_code(p_tenant_id uuid, p_type_id text, p_code text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_max_uses integer DEFAULT NULL::integer, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_code TEXT;\r\n  v_id   UUID;\r\n  v_base TEXT;\r\n  v_tries INT := 0;\r\nBEGIN\r\n  IF p_code IS NULL THEN\r\n    -- Auto-generar: formato ABC-12D3-XY (3-4-2, alfanumérico mayúsculas)\r\n    LOOP\r\n      v_code :=\r\n        upper(substr(md5(random()::text), 1, 3)) || '-' ||\r\n        upper(substr(md5(random()::text || clock_timestamp()::text), 1, 4)) || '-' ||\r\n        upper(substr(md5(clock_timestamp()::text), 1, 2));\r\n\r\n      EXIT WHEN NOT EXISTS (\r\n        SELECT 1 FROM public.codes WHERE code = v_code AND tenant_id = p_tenant_id\r\n      ) OR v_tries >= 20;\r\n      v_tries := v_tries + 1;\r\n    END LOOP;\r\n  ELSE\r\n    v_code := upper(trim(p_code));\r\n  END IF;\r\n\r\n  INSERT INTO public.codes (\r\n    tenant_id, code, type_id, description,\r\n    max_uses, expires_at, metadata, created_by\r\n  )\r\n  VALUES (\r\n    p_tenant_id, v_code, p_type_id, p_description,\r\n    p_max_uses, p_expires_at, p_metadata, auth.uid()\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  RETURN jsonb_build_object('ok', true, 'id', v_id, 'code', v_code);\r\n\r\nEXCEPTION WHEN unique_violation THEN\r\n  RETURN jsonb_build_object('ok', false, 'error', 'El código ya existe para este tenant');\r\nEND;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_create_code"
                },
                {
                    "arguments": "p_access_code text, p_metadata jsonb DEFAULT '{}'::jsonb",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_complete_access_onboarding(p_access_code text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'ong', 'rrhh'\nAS $function$\r\ndeclare\r\n  v_link          record;\r\n  v_user_id       uuid    := auth.uid();\r\n  v_membership_id uuid;\r\n  v_entity_id     uuid;\r\n  v_nombre        text;\r\n  v_apellido      text;\r\n  v_num_doc       text;\r\n  v_email         text;\r\n  v_context_type  text;\r\n  v_context_id    uuid;\r\nbegin\r\n  if v_user_id is null then\r\n    raise exception 'Not authenticated' using errcode = '28000';\r\n  end if;\r\n\r\n  select * into v_link\r\n  from public.access_links\r\n  where code = p_access_code\r\n    and is_active = true\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'Código de acceso no válido o inactivo'\r\n      using errcode = 'P0001';\r\n  end if;\r\n\r\n  if v_link.expires_at is not null and v_link.expires_at < now() then\r\n    update public.access_links set is_active = false where id = v_link.id;\r\n    raise exception 'El código de acceso ha expirado'\r\n      using errcode = 'P0001';\r\n  end if;\r\n\r\n  if v_link.used_count >= v_link.max_uses then\r\n    update public.access_links set is_active = false where id = v_link.id;\r\n    raise exception 'El código de acceso ha alcanzado su límite de usos'\r\n      using errcode = 'P0001';\r\n  end if;\r\n\r\n  insert into public.profiles (\r\n    id, tenant_id, full_name, tipo_documento, numero_documento\r\n  ) values (\r\n    v_user_id,\r\n    v_link.tenant_id,\r\n    nullif(trim(coalesce(p_metadata->>'full_name', '')), ''),\r\n    nullif(trim(coalesce(p_metadata->>'tipo_documento', '')), ''),\r\n    nullif(trim(coalesce(p_metadata->>'numero_documento', '')), '')\r\n  )\r\n  on conflict (id) do update\r\n    set tenant_id        = excluded.tenant_id,\r\n        full_name        = coalesce(excluded.full_name,        public.profiles.full_name),\r\n        tipo_documento   = coalesce(excluded.tipo_documento,   public.profiles.tipo_documento),\r\n        numero_documento = coalesce(excluded.numero_documento, public.profiles.numero_documento),\r\n        updated_at       = now();\r\n\r\n  -- Traducción target_type (access_links, inglés) → context_type (memberships, español).\r\n  -- GLOBAL no tiene equivalente puntual: se preserva tal cual (ahora permitido por el CHECK ampliado).\r\n  v_context_type := case v_link.target_type\r\n    when 'PROJECT'  then 'PROYECTO'\r\n    when 'PROGRAM'  then 'PROGRAMA'\r\n    when 'ACTIVITY' then 'ACTIVIDAD'\r\n    when 'SEDE'     then 'SEDE'\r\n    else 'GLOBAL'\r\n  end;\r\n\r\n  -- context_id es NOT NULL; GLOBAL no tiene target_id puntual, se usa el\r\n  -- propio tenant_id como identificador estable del contexto \"global\".\r\n  v_context_id := coalesce(v_link.target_id, v_link.tenant_id);\r\n\r\n  insert into public.memberships (\r\n    tenant_id, user_id, context_type, context_id, role_id, status\r\n  ) values (\r\n    v_link.tenant_id, v_user_id,\r\n    v_context_type, v_context_id,\r\n    v_link.assigned_role_id, 'active'\r\n  )\r\n  on conflict (tenant_id, user_id, context_type, context_id) do update\r\n    set status     = 'active',\r\n        role_id    = excluded.role_id,\r\n        updated_at = now()\r\n  returning id into v_membership_id;\r\n\r\n  if v_link.assigned_role_id is not null and v_link.assigned_sede_id is not null then\r\n    insert into public.user_roles_sedes (\r\n      tenant_id, user_id, role_id, sede_id\r\n    ) values (\r\n      v_link.tenant_id, v_user_id,\r\n      v_link.assigned_role_id, v_link.assigned_sede_id\r\n    )\r\n    on conflict do nothing;\r\n  end if;\r\n\r\n  v_nombre := nullif(trim(coalesce(\r\n    p_metadata->>'nombre',\r\n    split_part(coalesce(p_metadata->>'full_name', ''), ' ', 1)\r\n  )), '');\r\n\r\n  v_apellido := nullif(trim(coalesce(\r\n    p_metadata->>'apellido',\r\n    case\r\n      when strpos(coalesce(p_metadata->>'full_name', ''), ' ') > 0\r\n      then substring(\r\n             coalesce(p_metadata->>'full_name', '')\r\n             from strpos(coalesce(p_metadata->>'full_name', ''), ' ') + 1\r\n           )\r\n      else null\r\n    end\r\n  )), '');\r\n\r\n  v_num_doc := nullif(trim(coalesce(p_metadata->>'numero_documento', '')), '');\r\n\r\n  v_email := coalesce(\r\n    nullif(trim(coalesce(p_metadata->>'email', '')), ''),\r\n    (select au.email from auth.users au where au.id = v_user_id)\r\n  );\r\n\r\n  if v_link.type = 'VOLUNTEER_JOIN' then\r\n    select id into v_entity_id\r\n    from ong.voluntarios\r\n    where tenant_id = v_link.tenant_id\r\n      and iam_user_id = v_user_id\r\n    limit 1;\r\n\r\n    if v_entity_id is null then\r\n      insert into ong.voluntarios (\r\n        tenant_id, iam_user_id,\r\n        nombre, apellido, numero_documento,\r\n        codigo_estado, email\r\n      ) values (\r\n        v_link.tenant_id, v_user_id,\r\n        coalesce(v_nombre,   'Sin nombre'),\r\n        coalesce(v_apellido, 'Sin apellido'),\r\n        coalesce(v_num_doc,  'PENDIENTE'),\r\n        'en_proceso',\r\n        v_email\r\n      )\r\n      returning id into v_entity_id;\r\n    end if;\r\n\r\n  elsif v_link.type = 'STAFF_JOIN' then\r\n    insert into rrhh.solicitudes_admision (\r\n      tenant_id, nombres, apellidos, email, estado, fecha_solicitud\r\n    ) values (\r\n      v_link.tenant_id,\r\n      coalesce(v_nombre,   'Sin nombre'),\r\n      coalesce(v_apellido, 'Sin apellido'),\r\n      coalesce(v_email,    'sin-email@pendiente.local'),\r\n      'nueva',\r\n      now()\r\n    )\r\n    returning id into v_entity_id;\r\n\r\n  end if;\r\n\r\n  update public.access_links\r\n  set used_count = used_count + 1,\r\n      is_active  = case when (used_count + 1) >= max_uses then false else true end\r\n  where id = v_link.id;\r\n\r\n  insert into public.audit_logs (\r\n    tenant_id, actor_id, event_type, resource_name,\r\n    payload_after, criticality, retention_until\r\n  ) values (\r\n    v_link.tenant_id, v_user_id,\r\n    'ONBOARDING_COMPLETED', 'access_links',\r\n    jsonb_build_object(\r\n      'link_id',       v_link.id,\r\n      'link_code',     v_link.code,\r\n      'link_type',     v_link.type,\r\n      'membership_id', v_membership_id,\r\n      'entity_id',     v_entity_id\r\n    ),\r\n    'medium',\r\n    now() + make_interval(days => coalesce(\r\n      (select pp.retention_days\r\n       from public.tenants t\r\n       join public.plan_policies pp on pp.plan_id = t.plan_id\r\n       where t.id = v_link.tenant_id\r\n       limit 1),\r\n      180\r\n    ))\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'success',       true,\r\n    'membership_id', v_membership_id,\r\n    'entity_id',     v_entity_id,\r\n    'tenant_id',     v_link.tenant_id,\r\n    'link_type',     v_link.type\r\n  );\r\n\r\nexception\r\n  when others then\r\n    raise exception '%', sqlerrm using errcode = sqlstate;\r\nend;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_complete_access_onboarding"
                },
                {
                    "arguments": "",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_sync_urs_to_membership()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_remaining_role_id uuid;\nbegin\n  -- ── INSERT ─────────────────────────────────────────────────\n  if tg_op = 'INSERT' then\n    insert into public.memberships (\n      tenant_id, user_id, context_type, context_id, role_id, status\n    ) values (\n      new.tenant_id, new.user_id, 'SEDE', new.sede_id, new.role_id, 'active'\n    )\n    on conflict (tenant_id, user_id, context_type, context_id) do update\n      set role_id    = excluded.role_id,\n          status     = 'active',\n          updated_at = now();\n\n  -- ── UPDATE ─────────────────────────────────────────────────\n  elsif tg_op = 'UPDATE' then\n    if old.sede_id is distinct from new.sede_id then\n      -- Sede cambió: desactivar membresía de la sede vieja (si ya no quedan roles ahí)\n      select urs2.role_id into v_remaining_role_id\n      from public.user_roles_sedes urs2\n      join public.roles r2 on r2.id = urs2.role_id\n      where urs2.tenant_id = old.tenant_id\n        and urs2.user_id   = old.user_id\n        and urs2.sede_id   = old.sede_id\n      order by r2.hierarchy_level asc\n      limit 1;\n\n      if v_remaining_role_id is not null then\n        update public.memberships\n        set role_id = v_remaining_role_id, updated_at = now()\n        where tenant_id    = old.tenant_id\n          and user_id      = old.user_id\n          and context_type = 'SEDE'\n          and context_id   = old.sede_id;\n      else\n        update public.memberships\n        set status = 'inactive', updated_at = now()\n        where tenant_id    = old.tenant_id\n          and user_id      = old.user_id\n          and context_type = 'SEDE'\n          and context_id   = old.sede_id;\n      end if;\n\n      -- Crear/activar membresía en la nueva sede\n      insert into public.memberships (\n        tenant_id, user_id, context_type, context_id, role_id, status\n      ) values (\n        new.tenant_id, new.user_id, 'SEDE', new.sede_id, new.role_id, 'active'\n      )\n      on conflict (tenant_id, user_id, context_type, context_id) do update\n        set role_id = excluded.role_id, status = 'active', updated_at = now();\n\n    else\n      -- Misma sede: actualizar rol si cambió\n      if old.role_id is distinct from new.role_id then\n        update public.memberships\n        set role_id = new.role_id, updated_at = now()\n        where tenant_id    = new.tenant_id\n          and user_id      = new.user_id\n          and context_type = 'SEDE'\n          and context_id   = new.sede_id;\n      end if;\n    end if;\n\n  -- ── DELETE ─────────────────────────────────────────────────\n  elsif tg_op = 'DELETE' then\n    -- ¿Queda algún otro rol para el mismo user+sede?\n    select urs2.role_id into v_remaining_role_id\n    from public.user_roles_sedes urs2\n    join public.roles r2 on r2.id = urs2.role_id\n    where urs2.tenant_id = old.tenant_id\n      and urs2.user_id   = old.user_id\n      and urs2.sede_id   = old.sede_id\n    order by r2.hierarchy_level asc\n    limit 1;\n\n    if v_remaining_role_id is not null then\n      -- Actualizar la membresía al rol heredero\n      update public.memberships\n      set role_id = v_remaining_role_id, updated_at = now()\n      where tenant_id    = old.tenant_id\n        and user_id      = old.user_id\n        and context_type = 'SEDE'\n        and context_id   = old.sede_id;\n    else\n      -- Sin roles restantes: marcar membresía como inactiva\n      update public.memberships\n      set status = 'inactive', updated_at = now()\n      where tenant_id    = old.tenant_id\n        and user_id      = old.user_id\n        and context_type = 'SEDE'\n        and context_id   = old.sede_id;\n    end if;\n  end if;\n\n  return coalesce(new, old);\nend;\n$function$\n",
                    "return_type": "trigger",
                    "function_name": "fn_sync_urs_to_membership"
                },
                {
                    "arguments": "p_code text",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_validate_access_code(p_code text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_link record;\nbegin\n  select id, type, target_type, expires_at, is_active,\n         max_uses, used_count, onboarding_flow\n  into   v_link\n  from   public.access_links\n  where  code = p_code\n  limit  1;\n\n  if not found then\n    return jsonb_build_object('valid', false, 'reason', 'not_found');\n  end if;\n\n  if not v_link.is_active then\n    return jsonb_build_object('valid', false, 'reason', 'inactive');\n  end if;\n\n  if v_link.expires_at is not null and v_link.expires_at < now() then\n    return jsonb_build_object('valid', false, 'reason', 'expired');\n  end if;\n\n  if v_link.used_count >= v_link.max_uses then\n    return jsonb_build_object('valid', false, 'reason', 'limit_reached');\n  end if;\n\n  return jsonb_build_object(\n    'valid',           true,\n    'type',            v_link.type,\n    'target_type',     v_link.target_type,\n    'onboarding_flow', v_link.onboarding_flow,\n    'expires_at',      v_link.expires_at\n  );\nend;\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_validate_access_code"
                },
                {
                    "arguments": "p_url text",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_update_my_avatar(p_url text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'gym'\nAS $function$\r\nDECLARE\r\n  v_uid UUID := auth.uid();\r\nBEGIN\r\n  IF v_uid IS NULL THEN\r\n    RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated');\r\n  END IF;\r\n\r\n  -- Actualizar fuente de verdad universal\r\n  UPDATE public.profiles\r\n     SET avatar_url = p_url,\r\n         updated_at = now()\r\n   WHERE id = v_uid;\r\n\r\n  -- Sincronizar en gym.usuarios (si el usuario tiene perfil gym)\r\n  UPDATE gym.usuarios\r\n     SET foto_url   = p_url,\r\n         updated_at = now()\r\n   WHERE id_usuario = v_uid;\r\n\r\n  RETURN jsonb_build_object('ok', true, 'avatar_url', p_url);\r\nEND;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_update_my_avatar"
                },
                {
                    "arguments": "p_user_id uuid, p_context_id uuid",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_has_context_access(p_user_id uuid, p_context_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select exists (\n    select 1\n    from   public.memberships\n    where  tenant_id   = public.fn_current_tenant_id()\n      and  user_id     = p_user_id\n      and  context_id  = p_context_id\n      and  status      = 'active'\n  );\n$function$\n",
                    "return_type": "boolean",
                    "function_name": "fn_has_context_access"
                },
                {
                    "arguments": "p_code_id uuid, p_reason text DEFAULT NULL::text",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_revoke_code(p_code_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  UPDATE public.codes\r\n     SET status   = 'revoked',\r\n         metadata = metadata || jsonb_build_object(\r\n           'revoked_by',     auth.uid(),\r\n           'revoke_reason',  p_reason,\r\n           'revoked_at',     now()\r\n         )\r\n   WHERE id        = p_code_id\r\n     AND tenant_id = public.fn_current_tenant_id()\r\n     AND status   != 'revoked';\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object(\r\n      'ok', false,\r\n      'error', 'Código no encontrado, ya revocado, o no pertenece a tu tenant'\r\n    );\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object('ok', true, 'code_id', p_code_id);\r\nEND;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_revoke_code"
                },
                {
                    "arguments": "",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_my_permissions()\n RETURNS TABLE(permission text, role_name text)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  WITH base AS (\r\n    SELECT DISTINCT rp.permission, r.name AS role_name\r\n    FROM public.user_roles ur\r\n    JOIN public.roles r             ON r.id = ur.role_id\r\n    JOIN public.role_permissions rp ON rp.role_id = ur.role_id\r\n    WHERE ur.user_id   = auth.uid()\r\n      AND ur.tenant_id = public.fn_current_tenant_id()\r\n      AND (ur.expires_at IS NULL OR ur.expires_at > now())\r\n  ),\r\n  grants AS (\r\n    SELECT o.permission, 'override:grant'::text AS role_name\r\n    FROM public.user_permission_overrides o\r\n    WHERE o.user_id = auth.uid()\r\n      AND o.tenant_id = public.fn_current_tenant_id()\r\n      AND o.effect = 'grant'\r\n      AND (o.expires_at IS NULL OR o.expires_at > now())\r\n  ),\r\n  denies AS (\r\n    SELECT o.permission\r\n    FROM public.user_permission_overrides o\r\n    WHERE o.user_id = auth.uid()\r\n      AND o.tenant_id = public.fn_current_tenant_id()\r\n      AND o.effect = 'deny'\r\n      AND (o.expires_at IS NULL OR o.expires_at > now())\r\n  )\r\n  SELECT permission, role_name\r\n  FROM ( SELECT * FROM base UNION SELECT * FROM grants ) u\r\n  WHERE permission NOT IN (SELECT permission FROM denies)\r\n  ORDER BY permission\r\n$function$\n",
                    "return_type": "TABLE(permission text, role_name text)",
                    "function_name": "fn_my_permissions"
                },
                {
                    "arguments": "p_permission text",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_has_permission(p_permission text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT\r\n    ( EXISTS (\r\n        SELECT 1 FROM public.user_roles ur\r\n        JOIN public.role_permissions rp ON rp.role_id = ur.role_id\r\n        WHERE ur.user_id=auth.uid() AND ur.tenant_id=public.fn_current_tenant_id()\r\n          AND rp.permission=p_permission\r\n          AND (ur.expires_at IS NULL OR ur.expires_at > now())\r\n      )\r\n      OR EXISTS (\r\n        SELECT 1 FROM public.user_permission_overrides o\r\n        WHERE o.user_id=auth.uid() AND o.tenant_id=public.fn_current_tenant_id()\r\n          AND o.permission=p_permission AND o.effect='grant'\r\n          AND (o.expires_at IS NULL OR o.expires_at > now())\r\n      )\r\n    )\r\n    AND NOT EXISTS (\r\n        SELECT 1 FROM public.user_permission_overrides o\r\n        WHERE o.user_id=auth.uid() AND o.tenant_id=public.fn_current_tenant_id()\r\n          AND o.permission=p_permission AND o.effect='deny'\r\n          AND (o.expires_at IS NULL OR o.expires_at > now())\r\n    )\r\n$function$\n",
                    "return_type": "boolean",
                    "function_name": "fn_has_permission"
                },
                {
                    "arguments": "",
                    "definition": "CREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'gym', 'public'\nAS $function$\r\nDECLARE\r\n  v_nombre        TEXT;\r\n  v_telefono      TEXT;\r\n  v_documento     TEXT;\r\n  v_fecha_nac     DATE;\r\n  v_genero        TEXT;\r\n  v_cargo         TEXT;\r\n  v_foto_url      TEXT;\r\n  v_rol           TEXT;\r\n  v_gym_nombre    TEXT;\r\n  v_gym_ruc       TEXT;\r\n  v_gym_ciudad    TEXT;\r\n  v_gym_pais      TEXT;\r\n  v_gym_direccion TEXT;\r\n  v_gym_telefono  TEXT;\r\n  v_gym_email     TEXT;\r\n  v_gym_plan      TEXT;\r\n  v_id_gimnasio   UUID;\r\n  v_tenant_id     UUID;\r\n  v_codigo        TEXT;\r\n  v_staff_code    TEXT;\r\n  v_code_id       UUID;\r\n  v_role_id       UUID;\r\n  v_gym_tenant    UUID;  -- [017] elevado desde bloque interno — necesario para filtro V1\r\nBEGIN\r\n  -- Extraer metadata\r\n  v_nombre     := COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'nombre'),    ''), split_part(NEW.email, '@', 1));\r\n  v_telefono   := NULLIF(TRIM(NEW.raw_user_meta_data->>'telefono'),  '');\r\n  v_documento  := NULLIF(TRIM(NEW.raw_user_meta_data->>'documento'), '');\r\n  v_genero     := NULLIF(NEW.raw_user_meta_data->>'genero',          '');\r\n  v_cargo      := NULLIF(TRIM(NEW.raw_user_meta_data->>'cargo'),     '');\r\n  v_foto_url   := NULLIF(TRIM(NEW.raw_user_meta_data->>'foto_url'),  '');\r\n  v_rol        := COALESCE(NULLIF(NEW.raw_user_meta_data->>'rol',    ''), 'miembro');\r\n  v_staff_code := NULLIF(UPPER(TRIM(NEW.raw_user_meta_data->>'staff_code')), '');\r\n\r\n  BEGIN\r\n    v_fecha_nac := (NEW.raw_user_meta_data->>'fecha_nacimiento')::DATE;\r\n  EXCEPTION WHEN OTHERS THEN v_fecha_nac := NULL; END;\r\n\r\n  IF v_genero NOT IN ('M', 'F', 'Otro') THEN v_genero := NULL; END IF;\r\n\r\n  -- ── SIEMPRE: perfil universal BD Maestra ─────────────────────────────────\r\n  INSERT INTO public.profiles (id, full_name, tipo_documento, numero_documento, genero)\r\n  VALUES (\r\n    NEW.id, v_nombre,\r\n    CASE WHEN v_documento IS NOT NULL THEN 'DNI' ELSE NULL END,\r\n    v_documento, v_genero\r\n  )\r\n  ON CONFLICT (id) DO UPDATE\r\n    SET full_name        = EXCLUDED.full_name,\r\n        tipo_documento   = COALESCE(EXCLUDED.tipo_documento,   profiles.tipo_documento),\r\n        numero_documento = COALESCE(EXCLUDED.numero_documento, profiles.numero_documento),\r\n        genero           = COALESCE(EXCLUDED.genero,           profiles.genero);\r\n\r\n  v_gym_nombre := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_nombre'), '');\r\n\r\n  -- ── CASO A: Onboarding — dueño registra su gimnasio ──────────────────────\r\n  IF v_gym_nombre IS NOT NULL THEN\r\n    v_gym_ruc       := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_ruc'),       '');\r\n    v_gym_ciudad    := COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_ciudad'), ''), 'Lima');\r\n    v_gym_pais      := COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_pais'),   ''), 'Perú');\r\n    v_gym_direccion := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_direccion'),  '');\r\n    v_gym_telefono  := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_telefono'),   '');\r\n    v_gym_email     := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_email'),      '');\r\n    v_gym_plan      := COALESCE(NULLIF(NEW.raw_user_meta_data->>'gym_plan',    ''), 'mediano');\r\n\r\n    -- 1. Registrar como organización en BD Maestra\r\n    INSERT INTO public.tenants (\r\n      name, tax_id, industry_type_id, plan_id, status_financial_id, max_licenses\r\n    )\r\n    VALUES (\r\n      v_gym_nombre,\r\n      COALESCE(v_gym_ruc, 'PENDIENTE-' || gen_random_uuid()::text),\r\n      'gym',\r\n      public._gym_plan_to_bd(v_gym_plan),\r\n      'FIN-PENDING',\r\n      public._gym_plan_to_licenses(v_gym_plan)\r\n    )\r\n    RETURNING id INTO v_tenant_id;\r\n\r\n    -- [018] Sembrar los 7 roles de sistema del nuevo tenant gym\r\n    PERFORM public.seed_gym_roles(v_tenant_id);\r\n\r\n    -- 2. Crear gym\r\n    v_codigo := public.generate_gym_code(v_gym_nombre);\r\n    INSERT INTO gym.gimnasios (\r\n      nombre, ruc, ciudad, pais, direccion, telefono, email,\r\n      plan_suscripcion, estado, tenant_id\r\n    )\r\n    VALUES (\r\n      v_gym_nombre, v_gym_ruc, v_gym_ciudad, v_gym_pais, v_gym_direccion,\r\n      v_gym_telefono, v_gym_email, v_gym_plan, 'activo', v_tenant_id\r\n    )\r\n    RETURNING id_gimnasio INTO v_id_gimnasio;\r\n\r\n    -- 3. Código de acceso (miembros)\r\n    INSERT INTO gym.codigos_acceso (id_gimnasio, codigo, tipo, descripcion)\r\n    VALUES (v_id_gimnasio, v_codigo, 'general', 'Codigo principal del gimnasio');\r\n\r\n    -- 4. Perfil gym del dueño\r\n    INSERT INTO gym.usuarios (\r\n      id_usuario, email, nombre, telefono, documento, fecha_nacimiento,\r\n      genero, foto_url, cargo, id_gimnasio, rol, estado\r\n    )\r\n    VALUES (\r\n      NEW.id, NEW.email, v_nombre, v_telefono, v_documento, v_fecha_nac,\r\n      v_genero, v_foto_url, COALESCE(v_cargo, 'Gerente General'),\r\n      v_id_gimnasio, 'gerente', 'activo'\r\n    )\r\n    ON CONFLICT (id_usuario) DO NOTHING;\r\n\r\n    -- 5. Vincular profile al tenant\r\n    UPDATE public.profiles SET tenant_id = v_tenant_id WHERE id = NEW.id;\r\n\r\n    -- 6. Asignar rol 'Administrador General' al dueño\r\n    SELECT id INTO v_role_id\r\n    FROM public.roles\r\n    WHERE tenant_id = v_tenant_id AND name = 'Administrador General';\r\n\r\n    IF v_role_id IS NOT NULL THEN\r\n      INSERT INTO public.user_roles (tenant_id, user_id, role_id)\r\n      VALUES (v_tenant_id, NEW.id, v_role_id)\r\n      ON CONFLICT DO NOTHING;\r\n    END IF;\r\n\r\n  -- ── CASO B: Signup con código (miembro o staff) ───────────────────────────\r\n  ELSIF NEW.raw_user_meta_data->>'id_gimnasio' IS NOT NULL THEN\r\n    v_id_gimnasio := (NEW.raw_user_meta_data->>'id_gimnasio')::uuid;\r\n\r\n    -- Perfil gym\r\n    INSERT INTO gym.usuarios (\r\n      id_usuario, email, nombre, telefono, documento, fecha_nacimiento,\r\n      genero, foto_url, id_gimnasio, rol, estado\r\n    )\r\n    VALUES (\r\n      NEW.id, NEW.email, v_nombre, v_telefono, v_documento, v_fecha_nac,\r\n      v_genero, v_foto_url, v_id_gimnasio, v_rol, 'activo'\r\n    )\r\n    ON CONFLICT (id_usuario) DO NOTHING;\r\n\r\n    -- Vincular al tenant\r\n    UPDATE public.profiles p\r\n       SET tenant_id = g.tenant_id\r\n      FROM gym.gimnasios g\r\n     WHERE g.id_gimnasio = v_id_gimnasio\r\n       AND p.id = NEW.id\r\n       AND g.tenant_id IS NOT NULL;\r\n\r\n    -- Si hay staff_code → asignar rol del code_grants\r\n    IF v_staff_code IS NOT NULL THEN\r\n\r\n      -- [017] V1: resolver tenant del gym ANTES del SELECT del código\r\n      SELECT g.tenant_id INTO v_gym_tenant\r\n      FROM gym.gimnasios g WHERE g.id_gimnasio = v_id_gimnasio;\r\n\r\n      -- [017] V1 + V3 + V4: SELECT con aislamiento tenant, tipo restringido y lock de fila\r\n      SELECT c.id, cg.role_id\r\n      INTO   v_code_id, v_role_id\r\n      FROM   public.codes c\r\n      JOIN   public.code_grants cg ON cg.code_id = c.id\r\n      WHERE  c.code      = v_staff_code\r\n        AND  c.status    = 'active'\r\n        AND  c.tenant_id = v_gym_tenant\r\n        AND  c.type_id   = 'USER_INVITE'\r\n        AND  (c.expires_at IS NULL OR c.expires_at > now())\r\n        AND  (c.max_uses IS NULL OR c.current_uses < c.max_uses)\r\n      LIMIT  1\r\n      FOR UPDATE OF c;\r\n\r\n      IF v_code_id IS NOT NULL THEN\r\n        INSERT INTO public.user_roles (tenant_id, user_id, role_id)\r\n        VALUES (v_gym_tenant, NEW.id, v_role_id)\r\n        ON CONFLICT DO NOTHING;\r\n\r\n        -- Consumir el código\r\n        UPDATE public.codes\r\n           SET current_uses = current_uses + 1,\r\n               status = CASE\r\n                 WHEN max_uses IS NOT NULL AND (current_uses + 1) >= max_uses THEN 'used'\r\n                 ELSE 'active'\r\n               END\r\n         WHERE id = v_code_id;\r\n\r\n        -- Registrar uso\r\n        INSERT INTO public.code_usages (code_id, tenant_id, used_by, module_name)\r\n        VALUES (v_code_id, v_gym_tenant, NEW.id, 'gym');\r\n      END IF;\r\n\r\n    ELSE\r\n      -- Sin staff_code → asignar rol 'Miembro' por defecto\r\n      SELECT g.tenant_id INTO v_tenant_id\r\n      FROM gym.gimnasios g WHERE g.id_gimnasio = v_id_gimnasio;\r\n\r\n      IF v_tenant_id IS NOT NULL THEN\r\n        SELECT id INTO v_role_id\r\n        FROM public.roles\r\n        WHERE tenant_id = v_tenant_id AND name = 'Miembro';\r\n\r\n        IF v_role_id IS NOT NULL THEN\r\n          INSERT INTO public.user_roles (tenant_id, user_id, role_id)\r\n          VALUES (v_tenant_id, NEW.id, v_role_id)\r\n          ON CONFLICT DO NOTHING;\r\n        END IF;\r\n      END IF;\r\n    END IF;\r\n\r\n  -- ── CASO C: Otro sistema ──────────────────────────────────────────────────\r\n  END IF;\r\n\r\n  RETURN NEW;\r\n\r\nEXCEPTION WHEN OTHERS THEN\r\n  RAISE WARNING 'handle_new_user FALLÓ para % (%) — Error: % [%]',\r\n    NEW.email, NEW.id, SQLERRM, SQLSTATE;\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
                    "return_type": "trigger",
                    "function_name": "handle_new_user"
                },
                {
                    "arguments": "p_target_tenant uuid, p_template_tenant uuid DEFAULT '2fbedbdb-a4af-4e27-9a1c-2d0eb555f4b6'::uuid",
                    "definition": "CREATE OR REPLACE FUNCTION public.seed_gym_roles(p_target_tenant uuid, p_template_tenant uuid DEFAULT '2fbedbdb-a4af-4e27-9a1c-2d0eb555f4b6'::uuid)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_inserted integer := 0;\r\nBEGIN\r\n  -- 1) Clonar los 7 roles de sistema desde la plantilla.\r\n  --    tenant_id EXPLÍCITO → nunca cae en fn_current_tenant_id()=NULL.\r\n  --    Idempotente vía NOT EXISTS por (tenant_id, name).\r\n  INSERT INTO public.roles (tenant_id, name, hierarchy_level, is_system_role)\r\n  SELECT p_target_tenant, r.name, r.hierarchy_level, true\r\n  FROM public.roles r\r\n  WHERE r.tenant_id = p_template_tenant\r\n    AND r.is_system_role = true\r\n    AND NOT EXISTS (\r\n      SELECT 1 FROM public.roles x\r\n      WHERE x.tenant_id = p_target_tenant AND x.name = r.name\r\n    );\r\n  GET DIAGNOSTICS v_inserted = ROW_COUNT;\r\n\r\n  -- 2) Clonar role_permissions emparejando por NOMBRE de rol entre tenants.\r\n  --    Idempotente vía NOT EXISTS por (role_id, permission).\r\n  INSERT INTO public.role_permissions (role_id, permission)\r\n  SELECT tgt.id, rp.permission\r\n  FROM public.roles tpl\r\n  JOIN public.role_permissions rp ON rp.role_id = tpl.id\r\n  JOIN public.roles tgt\r\n        ON tgt.tenant_id = p_target_tenant\r\n       AND tgt.name      = tpl.name\r\n  WHERE tpl.tenant_id = p_template_tenant\r\n    AND NOT EXISTS (\r\n      SELECT 1 FROM public.role_permissions e\r\n      WHERE e.role_id = tgt.id AND e.permission = rp.permission\r\n    );\r\n\r\n  RETURN v_inserted;\r\nEND;\r\n$function$\n",
                    "return_type": "integer",
                    "function_name": "seed_gym_roles"
                },
                {
                    "arguments": "p_tenant_id uuid, p_role_id uuid, p_description text DEFAULT NULL::text, p_max_uses integer DEFAULT 1, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_custom_code text DEFAULT NULL::text",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_create_staff_code(p_tenant_id uuid, p_role_id uuid, p_description text DEFAULT NULL::text, p_max_uses integer DEFAULT 1, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_custom_code text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_result  JSONB;\r\n  v_code_id UUID;\r\n  v_code    TEXT;\r\n  v_allowed BOOLEAN;\r\nBEGIN\r\n  -- [019c] Validar el permiso contra el stack GYM (user_roles), que es donde el\r\n  --        onboarding gym asigna roles. Consulta directa → evita la ambigüedad de\r\n  --        overload de fn_has_permission y apunta a la tabla correcta para este flujo.\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.user_roles ur\r\n    JOIN public.roles r             ON r.id = ur.role_id\r\n    JOIN public.role_permissions rp ON rp.role_id = r.id\r\n    WHERE ur.user_id   = auth.uid()\r\n      AND ur.tenant_id = p_tenant_id\r\n      AND rp.permission = 'gym.codigos.crear'\r\n      AND (ur.expires_at IS NULL OR ur.expires_at > now())\r\n  ) INTO v_allowed;\r\n\r\n  IF NOT v_allowed THEN\r\n    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso: gym.codigos.crear requerido');\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.roles WHERE id = p_role_id AND tenant_id = p_tenant_id\r\n  ) THEN\r\n    RETURN jsonb_build_object('ok', false, 'error', 'El rol no pertenece a este tenant');\r\n  END IF;\r\n\r\n  SELECT public.fn_create_code(\r\n    p_tenant_id   => p_tenant_id,\r\n    p_type_id     => 'USER_INVITE',\r\n    p_code        => p_custom_code,\r\n    p_description => COALESCE(p_description, 'Código de staff'),\r\n    p_max_uses    => p_max_uses,\r\n    p_expires_at  => p_expires_at,\r\n    p_metadata    => jsonb_build_object('role_id', p_role_id)\r\n  ) INTO v_result;\r\n\r\n  IF NOT (v_result->>'ok')::boolean THEN\r\n    RETURN v_result;\r\n  END IF;\r\n\r\n  v_code_id := (v_result->>'id')::uuid;\r\n  v_code    := v_result->>'code';\r\n\r\n  INSERT INTO public.code_grants (code_id, role_id)\r\n  VALUES (v_code_id, p_role_id);\r\n\r\n  RETURN jsonb_build_object(\r\n    'ok', true, 'code_id', v_code_id, 'code', v_code,\r\n    'role_id', p_role_id, 'max_uses', p_max_uses, 'expires_at', p_expires_at\r\n  );\r\nEND;\r\n$function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_create_staff_code"
                },
                {
                    "arguments": "p_permission text",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_check_permission(p_permission text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT\r\n    ( EXISTS (\r\n        SELECT 1 FROM public.user_roles ur\r\n        JOIN public.role_permissions rp ON rp.role_id = ur.role_id\r\n        WHERE ur.user_id=auth.uid() AND ur.tenant_id=public.fn_current_tenant_id()\r\n          AND rp.permission=p_permission\r\n          AND (ur.expires_at IS NULL OR ur.expires_at > now())\r\n      )\r\n      OR EXISTS (\r\n        SELECT 1 FROM public.user_permission_overrides o\r\n        WHERE o.user_id=auth.uid() AND o.tenant_id=public.fn_current_tenant_id()\r\n          AND o.permission=p_permission AND o.effect='grant'\r\n          AND (o.expires_at IS NULL OR o.expires_at > now())\r\n      )\r\n    )\r\n    AND NOT EXISTS (\r\n        SELECT 1 FROM public.user_permission_overrides o\r\n        WHERE o.user_id=auth.uid() AND o.tenant_id=public.fn_current_tenant_id()\r\n          AND o.permission=p_permission AND o.effect='deny'\r\n          AND (o.expires_at IS NULL OR o.expires_at > now())\r\n    )\r\n$function$\n",
                    "return_type": "boolean",
                    "function_name": "fn_check_permission"
                },
                {
                    "arguments": "p_codigo text",
                    "definition": "CREATE OR REPLACE FUNCTION public.fn_lookup_gym_access(p_codigo text)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'gym', 'public'\nAS $function$\r\nDECLARE\r\n  v RECORD;\r\nBEGIN\r\n  SELECT c.id_gimnasio, g.nombre, g.ciudad, g.estado, g.tenant_id\r\n    INTO v\r\n    FROM gym.codigos_acceso c\r\n    JOIN gym.gimnasios g ON g.id_gimnasio = c.id_gimnasio\r\n   WHERE c.codigo = p_codigo\r\n     AND c.activo = true\r\n     AND (c.fecha_expiracion IS NULL OR c.fecha_expiracion > now())\r\n   LIMIT 1;\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object('found', false);\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object(\r\n    'found',       true,\r\n    'id_gimnasio', v.id_gimnasio,\r\n    'nombre',      v.nombre,\r\n    'ciudad',      v.ciudad,\r\n    'estado',      v.estado,\r\n    'tenant_id',   v.tenant_id\r\n  );\r\nEND $function$\n",
                    "return_type": "jsonb",
                    "function_name": "fn_lookup_gym_access"
                }
            ]
        },
        {
            "schema": "ong",
            "functions": [
                {
                    "arguments": "p_qr_payload text, p_id_actividad uuid, p_scan_time timestamp with time zone DEFAULT now()",
                    "definition": "CREATE OR REPLACE FUNCTION ong.fn_register_attendance_scan(p_qr_payload text, p_id_actividad uuid, p_scan_time timestamp with time zone DEFAULT now())\n RETURNS ong.asistencias\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nDECLARE\r\n  v_card ong.id_cards;\r\n  v_asistencia ong.asistencias;\r\nBEGIN\r\n  IF NOT public.fn_has_permission('attendance.scan') AND NOT public.fn_is_tenant_admin() THEN\r\n    RAISE EXCEPTION 'No autorizado';\r\n  END IF;\r\n\r\n  SELECT *\r\n  INTO v_card\r\n  FROM ong.id_cards\r\n  WHERE tenant_id = public.fn_current_tenant_id()\r\n    AND qr_payload = p_qr_payload\r\n    AND estado = 'activa'\r\n    AND (expires_at IS NULL OR expires_at > p_scan_time)\r\n  LIMIT 1;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Credencial no encontrada o inactiva';\r\n  END IF;\r\n\r\n  SELECT *\r\n  INTO v_asistencia\r\n  FROM ong.asistencias\r\n  WHERE tenant_id = public.fn_current_tenant_id()\r\n    AND id_actividad = p_id_actividad\r\n    AND id_voluntario = v_card.id_voluntario\r\n    AND fecha_operacion = p_scan_time::date\r\n    AND is_deleted = false\r\n  LIMIT 1\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    INSERT INTO ong.asistencias(\r\n      tenant_id, id_actividad, id_voluntario, fecha_operacion,\r\n      check_in_at, origen_registro, estado, qr_payload, id_card_id,\r\n      created_by, updated_by\r\n    )\r\n    VALUES(\r\n      public.fn_current_tenant_id(), p_id_actividad, v_card.id_voluntario, p_scan_time::date,\r\n      p_scan_time, 'scan', 'presente', p_qr_payload, v_card.id,\r\n      auth.uid(), auth.uid()\r\n    )\r\n    RETURNING * INTO v_asistencia;\r\n  ELSE\r\n    UPDATE ong.asistencias\r\n    SET check_out_at = COALESCE(v_asistencia.check_out_at, p_scan_time),\r\n        updated_at = now(),\r\n        updated_by = auth.uid()\r\n    WHERE id = v_asistencia.id\r\n    RETURNING * INTO v_asistencia;\r\n  END IF;\r\n\r\n  RETURN v_asistencia;\r\nEND;\r\n$function$\n",
                    "return_type": "ong.asistencias",
                    "function_name": "fn_register_attendance_scan"
                }
            ]
        },
        {
            "schema": "telemetria",
            "functions": [
